// Generated by grafana-k6 on 2026-11-02T04:13:56Z
/**
 * Event-day load: 100 participants arrive over 30 s, log in, open /me (redirects to /team) and keep
 * refreshing it; each team's driver saves a draft, then all 50 drivers lock their investments at the
 * same moment. Needs `node --env-file=.env.local k6/seed.mjs` first. Run: k6 run k6/scripts/event-load.js
 *
 * Login and investing are Next.js server actions, not a REST API. The action ids change on every
 * deploy, so setup() reads them from the live site the same way the browser gets them.
 */
import http from 'k6/http';
import { check, fail, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import exec from 'k6/execution';

const BASE_URL = __ENV.BASE_URL || 'https://tinder-for-startups.vercel.app';
const ARRIVE_S = 30; // everyone logs in within this window
const BURST_S = 60; // drivers lock this long after setup
const AFTER_S = 60; // keep refreshing after the burst
const AMOUNTS = [200, 300, 400, 500, 600, 700, 2300]; // distinct, multiples of ₹100, sum ₹5,000

const users = new SharedArray('users', () => JSON.parse(open('../.seed.json')));

export const options = {
  scenarios: {
    event: { executor: 'per-vu-iterations', vus: Number(__ENV.VUS || users.length), iterations: 1, maxDuration: '5m' },
  },
  thresholds: {
    http_req_failed: ['rate<0.01'],
    checks: ['rate>0.99'],
    'http_req_duration{name:login}': ['p(95)<3000'],
    'http_req_duration{name:team}': ['p(95)<2000'],
    'http_req_duration{name:team refresh}': ['p(95)<2000'],
    'http_req_duration{name:lock}': ['p(95)<3000'],
  },
  summaryTrendStats: ['avg', 'med', 'p(95)', 'p(99)', 'max'],
};

// Calls a server action the way React's encodeReply does for action(prevState, formData).
function callAction(path, id, fields, name) {
  const b = 'k6formboundary';
  const parts = Object.entries(fields).map(([k, v]) => [`_1_${k}`, v]);
  parts.push(['0', '["$undefined","$K1"]']);
  const body = parts.map(([k, v]) => `--${b}\r\nContent-Disposition: form-data; name="${k}"\r\n\r\n${v}\r\n`).join('') + `--${b}--\r\n`;
  return http.post(`${BASE_URL}${path}`, body, {
    headers: { 'Next-Action': id, Accept: 'text/x-component', 'Content-Type': `multipart/form-data; boundary=${b}` },
    redirects: 0,
    tags: { name },
  });
}

function login(user, loginId) {
  const res = callAction('/login', loginId, { participantId: user.id, code: user.code }, 'login');
  if (!check(res, { 'login redirects to /me': (r) => (r.headers['X-Action-Redirect'] || '').startsWith('/me') })) {
    fail(`login failed for ${user.id}: ${res.status} ${String(res.body).slice(-200)}`);
  }
}

export function setup() {
  // Login form gets its action from the server: {"id":"<hex>","bound":null} in the RSC payload.
  const page = http.get(`${BASE_URL}/login`).body;
  const loginId = (/\\"id\\":\\"([0-9a-f]{40,})\\",\\"bound\\":null/.exec(page) || [])[1];
  if (!loginId) fail('login action id not found on /login');

  // MarketplacePanel imports its actions in client JS: createServerReference)("<hex>",…,"lockAllocation")
  login(users[0], loginId);
  const team = http.get(`${BASE_URL}/team`).body;
  const ids = {};
  for (const chunk of new Set(team.match(/\/_next\/static\/[^"\\]+\.js/g))) {
    for (const m of http.get(`${BASE_URL}${chunk}`).body.matchAll(/createServerReference\)\("([0-9a-f]+)",[^)]*?"(\w+)"\)/g)) {
      ids[m[2]] = m[1];
    }
  }
  if (!ids.saveAllocation || !ids.lockAllocation) fail('marketplace action ids not found; is the event in phase 6?');
  const burstAt = Date.now() + BURST_S * 1000;
  return { loginId, saveId: ids.saveAllocation, lockId: ids.lockAllocation, burstAt, endAt: burstAt + AFTER_S * 1000 };
}

export default function (s) {
  const me = users[exec.vu.idInTest - 1];
  const items = JSON.stringify(me.targets.map((target, i) => ({ target, amount: AMOUNTS[i] })));
  sleep(Math.random() * ARRIVE_S);

  check(http.get(`${BASE_URL}/login`, { tags: { name: 'login page' } }), { 'login page 200': (r) => r.status === 200 });
  login(me, s.loginId);
  check(http.get(`${BASE_URL}/me`, { tags: { name: 'team' } }), {
    '/me lands on /team': (r) => r.status === 200 && r.url.endsWith('/team'),
  });

  if (me.driver) {
    sleep(1 + Math.random() * 5);
    check(callAction('/team', s.saveId, { items }, 'save draft'), { 'draft saved': (r) => r.body.includes('Draft saved') });
  }

  let locked = !me.driver;
  while (Date.now() < s.endAt) {
    if (!locked && Date.now() >= s.burstAt) {
      check(callAction('/team', s.lockId, { items }, 'lock'), { locked: (r) => r.body.includes('Locked!') });
      locked = true;
    } else {
      // LiveRefresh's router.refresh() fetches the RSC payload, not HTML.
      check(http.get(`${BASE_URL}/team`, { headers: { RSC: '1' }, tags: { name: 'team refresh' } }), {
        'refresh 200': (r) => r.status === 200,
      });
    }
    const think = 5 + Math.random() * 5;
    sleep(locked ? think : Math.min(think, Math.max(0, (s.burstAt - Date.now()) / 1000)));
  }
}
